            return _eye39to41(irisDark, irisLight);
        }

        revert("idx");
    }

    function encodeWithTransform(
        string memory input
    ) internal pure returns (string memory) {
        return
            string(
                abi.encodePacked(
                    '<g transform="translate(-2,1)"><path fill="#',
                    input,
                    '"/></g>'
