                    '<path fill="#',
                    irisLight,
                    '" d="m12 11v1h1v-1zm4 0v1h1v-1z"/>',
                    "</g>"
                )
            );
    }

    function _eye39to41IrisPair(
        uint256 i
    ) private pure returns (string memory irisDark, string memory irisLight) {
        if (i == 39) return ("784421", "c87137");
        if (i == 40) return ("217821", "37c837");
        return ("0088aa", "00ccff");
    }
}

